const f = $input.first().json;
const pick = (o, k) => (o[k] === undefined || o[k] === null ? '' : String(o[k]).trim());
return [{ json: { baseId: pick(f, 'Clayroots Base ID'), tableId: pick(f, 'Table ID'), launchRecordId: '', triggerKind: 'form' } }];

// Hub launch path: the Airtable "get" nodes return {id, fields:{...}}; read through fields.
const clientRec = $input.first().json || {};
const client = clientRec.fields || clientRec;
const launchRec = $('Read Launch Record').first().json || {};
const launch = launchRec.fields || launchRec;
const baseId = String(client['Clayroots Base ID'] || '').trim();
const tableId = String(launch['Table ID'] || launch['Target'] || '').trim();
if (!/^app[A-Za-z0-9]{14}$/.test(baseId)) {
  throw new Error('The launch record does not resolve to a Clayroots Base ID (Client link missing or the client has no base). Nothing was written.');
}
if (!/^tbl[A-Za-z0-9]{14}$/.test(tableId)) {
  throw new Error('The launch record carries no Table ID. Nothing was written.');
}
return [{ json: { baseId, tableId, launchRecordId: String(launchRec.id || ''), triggerKind: 'form' } }];

const i = $input.first().json;
const baseId = String(i.baseId || '').trim();
const tableId = String(i.tableId || '').trim();
if (!/^app[A-Za-z0-9]{14}$/.test(baseId)) {
  throw new Error('Clayroots Base ID ' + baseId + ' is not a valid base id. Nothing was written.');
}
if (!/^tbl[A-Za-z0-9]{14}$/.test(tableId)) {
  throw new Error('Table ID ' + tableId + ' is not a valid table id. Nothing was written.');
}
return [{ json: { baseId, tableId, launchRecordId: String(i.launchRecordId || ''), triggerKind: String(i.triggerKind || 'form'), startedAt: new Date().toISOString() } }];

const cfg = $('Resolve Inputs').first().json;
const tables = [];
for (const it of $input.all()) {
  const r = it.json;
  if (Array.isArray(r.tables)) { for (const t of r.tables) tables.push(t); }
  else if (r && r.id) tables.push(r);
}
const table = tables.find(t => t && t.id === cfg.tableId);
if (!table) {
  throw new Error('Table ' + cfg.tableId + ' does not resolve in base ' + cfg.baseId + '. Nothing was written.');
}
const fields = (table.fields || []).filter(f => f && typeof f.name === 'string' && f.name.indexOf('_cc_') !== 0);
const companyField = fields.find(f => f.name === 'Company');
if (!companyField) {
  throw new Error('Table ' + (table.name || cfg.tableId) + ' (' + cfg.tableId + ') has no Company column. Nothing was written.');
}
const COMPUTED = ['formula','rollup','count','lookup','multipleLookupValues','aiText','autoNumber','createdTime','lastModifiedTime','createdBy','lastModifiedBy','button','externalSyncSource','barcode'];
if (COMPUTED.indexOf(companyField.type) > -1) {
  throw new Error('The Company column on ' + (table.name || cfg.tableId) + ' is a computed field (' + companyField.type + ') and cannot be written. Nothing was written.');
}
const cleanField = fields.find(f => f.name === 'company_clean') || null;
const cleanWritable = !!cleanField && COMPUTED.indexOf(cleanField.type) === -1;
let cleanNote;
if (!cleanField) { cleanNote = 'company_clean is absent on this table, wrote Company only'; }
else if (!cleanWritable) { cleanNote = 'company_clean is computed on this table (' + cleanField.type + '), wrote Company only'; }
else { cleanNote = 'wrote Company and company_clean'; }
const s = $getWorkflowStaticData('global');
s.ccn = s.ccn || {};
s.ccn[$execution.id] = { scanned: 0, changed: 0, unchanged: 0, blank: 0, quarantined: 0, pipe: 0, dash: 0, legal: 0, symbol: 0, pages: 0, batches: 0 };
const url = 'https://api.airtable.com/v0/' + cfg.baseId + '/' + cfg.tableId + '?pageSize=100';
return [{ json: { baseId: cfg.baseId, tableId: cfg.tableId, tableName: table.name || cfg.tableId, companyField: 'Company', cleanField: cleanField ? 'company_clean' : '', cleanType: cleanField ? cleanField.type : '', cleanWritable, cleanNote, pageUrl: url, more: true } }];

const cfg = $('Detect Company Columns').first().json;
const s = $getWorkflowStaticData('global');
s.ccn = s.ccn || {};
if (!s.ccn[$execution.id]) { s.ccn[$execution.id] = { scanned: 0, changed: 0, unchanged: 0, blank: 0, quarantined: 0, pipe: 0, dash: 0, legal: 0, symbol: 0, pages: 0, batches: 0 }; }
const st = s.ccn[$execution.id];

// The cleaning itself happened in the Clean Fields helper (previous node); this node only
// decides what to write and keeps the diagnostic counts of what kind of dirt each name carried.
const classify = (nm) => {
  const t = { pipe: false, dash: false, symbol: false, legal: false };
  let c = String(nm).trim();
  const p = c.indexOf(' | ');
  if (p > -1) { t.pipe = true; c = c.slice(0, p).trim(); }
  const d = c.search(/\s[-–—:]\s/);
  if (d >= 3) { t.dash = true; c = c.slice(0, d).trim(); }
  if (/[®™]/.test(c)) { t.symbol = true; c = c.replace(/[®™]/g, ''); }
  for (let i = 0; i < 2; i++) {
    const m = c.match(/[,\s]+(inc|llc|l\.l\.c\.|ltd|limited|corp|corporation|co|company|gmbh|plc|llp|lp|pllc|pc)\.?$/i);
    if (!m) break;
    const before = c.slice(0, m.index).trim();
    const lastWord = before.split(/\s+/).pop() || '';
    if (lastWord === '&') break;
    t.legal = true;
    c = before;
  }
  return t;
};

const GENERIC = ['home','shop','welcome','about','products','store','index','page','contact'];
const updates = [];
for (const it of $input.all()) {
  const r = it.json || {};
  if (r._empty || !r._recId) continue;
  st.scanned++;
  const companyRaw = String(r._companyRaw || '');
  const cleanRaw = String(r._cleanRaw || '');
  const source = String(r._source || '');
  if (!source.trim()) { st.blank++; continue; }
  const value = String(r.Company || '').trim();
  if (!value || value.length < 3 || GENERIC.indexOf(value.toLowerCase()) > -1) { st.quarantined++; continue; }
  const needCompany = companyRaw !== value;
  const needClean = !!cfg.cleanWritable && cleanRaw !== value;
  if (!needCompany && !needClean) { st.unchanged++; continue; }
  const t = classify(source);
  if (t.pipe) st.pipe++;
  if (t.dash) st.dash++;
  if (t.legal) st.legal++;
  if (t.symbol) st.symbol++;
  const payload = {};
  if (needCompany) payload[cfg.companyField] = value;
  if (needClean) payload[cfg.cleanField] = value;
  updates.push({ id: r._recId, fields: payload });
  st.changed++;
}

const chunks = [];
for (let i = 0; i < updates.length; i += 10) { chunks.push({ records: updates.slice(i, i + 10) }); }
st.pages++;
st.batches += chunks.length;

const resp = $('Fetch Page of 100').first().json || {};
const offset = resp.offset ? String(resp.offset) : '';
const nextUrl = offset ? ('https://api.airtable.com/v0/' + cfg.baseId + '/' + cfg.tableId + '?pageSize=100&offset=' + encodeURIComponent(offset)) : '';
return [{ json: { chunks, chunkCount: chunks.length, pageUrl: nextUrl, more: !!offset } }];

const cfg = $('Detect Company Columns').first().json;
const inp = $('Resolve Inputs').first().json;
const s = $getWorkflowStaticData('global');
s.ccn = s.ccn || {};
const st = s.ccn[$execution.id] || { scanned: 0, changed: 0, unchanged: 0, blank: 0, quarantined: 0, pipe: 0, dash: 0, legal: 0, symbol: 0, pages: 0, batches: 0 };
delete s.ccn[$execution.id];
const duration = Math.max(0, Math.round((Date.now() - new Date(inp.startedAt).getTime()) / 1000));
const columns = cfg.cleanWritable ? 'Company + company_clean' : 'Company';
const description = 'Cleaned company names on ' + cfg.tableName + ' (' + cfg.tableId + ') in ' + cfg.baseId + '.\n' +
  'Columns targeted: ' + columns + '. ' + cfg.cleanNote + '.\n' +
  'Scanned ' + st.scanned + ', changed ' + st.changed + ', already correct ' + st.unchanged + ', blank ' + st.blank + ', quarantined ' + st.quarantined + '.\n' +
  'Change types: pipe truncation ' + st.pipe + ', dash truncation ' + st.dash + ', legal suffix ' + st.legal + ', symbol ' + st.symbol + '.\n' +
  'Pages read ' + st.pages + ', write batches ' + st.batches + '.';
const fields = {
  'Execution ID': String($execution.id),
  'Automation': 'Clean Company Names on table',
  'Status': 'Succeeded',
  'Description': description,
  'Run at': inp.startedAt,
  'Target': cfg.tableName,
  'Table ID': cfg.tableId,
  'Duration s': duration,
  'Execution Link': 'https://n8n.flowroots.com/workflow/' + $workflow.id + '/executions/' + $execution.id,
  'Records In': st.scanned,
  'Records Out': st.changed,
  'Errors': 0,
  'Trigger': inp.launchRecordId ? 'form' : 'form'
};
const body = inp.launchRecordId ? { records: [{ id: inp.launchRecordId, fields }], typecast: true } : { records: [{ fields }], typecast: true };
return [{ json: { hasLaunchRecord: !!inp.launchRecordId, body, summary: description } }];

// One item per record of the page, shaped for the Clean Fields helper: Company carries the source
// the helper cleans, the raw values ride along for Plan Writes to diff against.
const cfg = $('Detect Company Columns').first().json;
const readVal = (v) => { if (v === null || v === undefined) return ''; if (typeof v === 'object') { return typeof v.value === 'string' ? v.value : ''; } return String(v); };
const resp = $input.first().json || {};
const records = Array.isArray(resp.records) ? resp.records : [];
const out = [];
for (const rec of records) {
  const f = (rec && rec.fields) || {};
  const companyRaw = readVal(f[cfg.companyField]);
  const cleanRaw = cfg.cleanField ? readVal(f[cfg.cleanField]) : '';
  const source = companyRaw.trim() ? companyRaw : cleanRaw;
  out.push({ json: { _recId: rec.id, _companyRaw: companyRaw, _cleanRaw: cleanRaw, _source: source, Company: source } });
}
// An empty page still has to reach Plan Writes (offset handling); the placeholder carries no record.
if (!out.length) return [{ json: { _empty: true } }];
return out;
